183: function applyEffects(state, effect = {}) {
184:   Object.entries(effect).forEach(([key, value]) => {
185:     if (!Object.prototype.hasOwnProperty.call(state, key)) return;
186:     state[key] += value;
187:   });
188: 
189:   state.crew = clamp(state.crew, 0, 99);
190:   state.morale = clamp(state.morale, 0, 100);
191:   state.supplies = clamp(state.supplies, 0, 100);
192:   state.shields = clamp(state.shields, 0, 100);
193:   state.scrap = clamp(state.scrap, 0, 999);
194:   state.reputation = clamp(state.reputation, -20, 20);
195: }
