239: function createStats(state) {
240:   const stats = [
241:     { label: 'Crew', value: state.crew },
242:     { label: 'Morale', value: `${state.morale}%` },
243:     { label: 'Supplies', value: `${state.supplies}%` },
244:     { label: 'Shields', value: `${state.shields}%` },
