279: function renderShop(state) {
280:   const sceneEl = document.getElementById('scene');
281:   const cards = shopItems.map((item) => {
282:     const owned = state.inventory.includes(item.id);
283:     const equipped = (item.kind === 'weapon' && state.weapon === item.name)
284:       || (item.kind === 'armor' && state.armor === item.name);
285:     const status = equipped ? 'Equipped' : owned ? 'Owned' : `${item.price} scrap`;
286:     const disabled = (owned && item.kind !== 'supply' && item.kind !== 'medkit') || state.scrap < item.price;
287:     const buttonText = equipped ? 'Equipped' : owned ? 'Already owned' : state.scrap < item.price ? 'Not enough scrap' : 'Purchase';
288:     return `<article class="shop-item">
289:       <div class="shop-item-head"><span class="choice-tag">${item.kind}</span><span class="shop-cost">${status}</span></div>
290:       <h3>${item.name}</h3><p>${item.detail}</p>
291:       <button class="choice-btn shop-buy" data-item="${item.id}" type="button" ${disabled ? 'disabled' : ''}><strong>${buttonText}</strong></button>
292:     </article>`;
293:   }).join('');
294: 
295:   sceneEl.innerHTML = `<div class="scene-top"><h2>Shipyard & Supply Deck</h2><span class="scene-badge">${state.scrap} scrap available</span></div>
296:     <div class="scene-body shop-layout"><div class="story-copy">
297:       <p>Upgrade the Arbiter before you commit to the Verge. Bought weapons and suits stay in your inventory; equipping a new one is free. Consumables take effect immediately.</p>
298:       <div class="shop-grid">${cards}</div>
299:     </div><aside class="side-panel">
300:       <div class="mission-box"><h3>Loadout</h3><p><strong>Weapon:</strong> ${state.weapon} (+${state.weaponBonus})<br><strong>Suit:</strong> ${state.armor} (+${state.armorBonus})</p></div>
301:       <div class="mission-box"><h3>Free expansions</h3><p>The Quiet Signal bonus episode is included at no cost. Open it any time from the top bar.</p></div>
302:       <button id="returnFromShop" class="ghost-btn" type="button">Return to voyage</button>
303:     </aside></div>`;
304: 
305:   sceneEl.querySelectorAll('.shop-buy').forEach((button) => {
306:     button.addEventListener('click', () => {
307:       const item = shopItems.find((entry) => entry.id === button.dataset.item);
308:       if (!item || state.scrap < item.price) return;
309:       if (item.kind !== 'supply' && item.kind !== 'medkit' && state.inventory.includes(item.id)) return;
310:       state.scrap -= item.price;
311:       if (item.kind === 'weapon') {
312:         state.inventory.push(item.id);
313:         state.weapon = item.name;
314:         state.weaponBonus = item.bonus;
315:         state.log.push(`Purchased and equipped ${item.name}.`);
316:       } else if (item.kind === 'armor') {
317:         state.inventory.push(item.id);
318:         state.armor = item.name;
319:         state.armorBonus = item.bonus;
320:         state.log.push(`Purchased and equipped ${item.name}.`);
321:       } else if (item.kind === 'supply') {
322:         state.supplies = clamp(state.supplies + 22, 0, 100);
323:         state.log.push('Field rations restored 22 supplies.');
324:       } else {
325:         state.crew = clamp(state.crew + 2, 0, 99);
326:         state.log.push('A crew medkit restored two crew.');
327:       }
328:       renderGame(state);
329:     });
330:   });
331:   document.getElementById('returnFromShop').addEventListener('click', () => {
332:     state.screen = 'story';
333:     renderGame(state);
334:   });
335: }
