337: function renderCombat(state, scene) {
338:   const sceneEl = document.getElementById('scene');
339:   const result = state.combatResult;
340:   const actionLabels = { attack: 'Fire weapon', maneuver: 'Evasive maneuver', negotiate: 'Open a channel' };
341:   const actionInfo = {
342:     attack: `Attack bonus: +${state.weaponBonus} weapon + ${Math.floor(state.morale / 25)} morale`,
343:     maneuver: `Maneuver bonus: +${state.armorBonus} suit + 2 pilot training`,
344:     negotiate: `Diplomacy bonus: +${Math.floor(state.reputation / 2)} reputation + ${Math.floor(state.morale / 20)} morale`
345:   };
346:   sceneEl.innerHTML = `<div class="scene-top"><h2>${scene.title}</h2><span class="scene-badge">${scene.badge}</span></div>
347:     <div class="scene-body combat-layout"><div class="story-copy">
348:       <p>${scene.text}</p>
349:       <div class="combat-console">
350:         <div class="enemy-card"><span class="eyebrow">Hostile contact · threat 14</span><strong>Verge Raider Skiff</strong><p>Hull 1 · Disruptor lock active</p></div>
351:         ${result ? `<div class="roll-result ${result.success ? 'good' : 'danger'}"><span class="die-face">${result.roll}</span><div><strong>${result.headline}</strong><p>d20 ${result.roll} + ${result.bonus} = ${result.total} vs DC ${result.dc}. ${result.message}</p></div></div>
352:           <button id="continueCombat" class="choice-btn" type="button"><strong>Continue to the Verge</strong></button>` : `<div class="action-list" role="group" aria-label="Combat approach">
353:           ${Object.entries(actionLabels).map(([key, label]) => `<button class="action-btn ${state.combatAction === key ? 'selected' : ''}" data-action="${key}" type="button"><strong>${label}</strong><span>${actionInfo[key]}</span></button>`).join('')}
354:         </div><button id="rollCombat" class="roll-btn" type="button">🎲 Roll d20 — ${actionLabels[state.combatAction]}</button><p class="dice-note">Natural 20: critical success · Natural 1: critical failure</p>`}
355:       </div>
356:     </div><aside class="side-panel"><div class="mission-box"><h3>Equipped</h3><p><strong>${state.weapon}</strong><br>Weapon bonus +${state.weaponBonus}<br><br><strong>${state.armor}</strong><br>Maneuver bonus +${state.armorBonus}</p></div><div class="outcome-box warn"><h3>Check</h3><p>Roll a d20 and add the bonus for your chosen approach. Meet or beat the DC to turn the ambush in your favor.</p></div></aside></div>`;
357: 
358:   if (result) {
359:     document.getElementById('continueCombat').addEventListener('click', () => {
360:       state.currentKey = 'intro';
361:       state.chapter = 'Departure';
362:       state.combatResult = null;
363:       renderGame(state);
364:     });
365:     return;
366:   }
367:   sceneEl.querySelectorAll('.action-btn').forEach((button) => {
368:     button.addEventListener('click', () => {
369:       state.combatAction = button.dataset.action;
370:       renderGame(state);
371:     });
372:   });
373:   document.getElementById('rollCombat').addEventListener('click', () => {
374:     const roll = Math.floor(Math.random() * 20) + 1;
375:     const bonuses = {
376:       attack: state.weaponBonus + Math.floor(state.morale / 25),
377:       maneuver: state.armorBonus + 2,
378:       negotiate: Math.floor(state.reputation / 2) + Math.floor(state.morale / 20)
379:     };
380:     const dc = state.combatAction === 'maneuver' ? 15 : state.combatAction === 'negotiate' ? 13 : 14;
381:     const bonus = bonuses[state.combatAction];
382:     const total = roll + bonus;
383:     const success = roll === 20 || (roll !== 1 && total >= dc);
384:     let headline;
385:     let message;
